package com.bank.dual.service;

import java.util.logging.Logger;

// Finds the two unmatched codes via XOR plus a distinguishing bit.
public class DualOrphanService {
    private static final Logger log = Logger.getLogger(DualOrphanService.class.getName());

    public int[] findTwoOrphans(int[] codes) {
        int x = 0;
        for (int code : codes) x ^= code;      // x = orphanA ^ orphanB
        int rightmostBit = x & -x;             // isolate a bit where they differ
        int num1 = 0, num2 = 0;
        for (int code : codes) {
            if ((code & rightmostBit) != 0) num1 ^= code; // bucket with the bit set
            else num2 ^= code;                             // bucket without it
        }
        log.info(() -> "Two unmatched codes = " + num1 + " and " + num2);
        return new int[]{num1, num2};
    }
}
