package com.bank.dual;

import com.bank.dual.service.DualOrphanService;
import java.util.Arrays;
import java.util.logging.Logger;

public class DualOrphanApplication {
    private static final Logger log = Logger.getLogger(DualOrphanApplication.class.getName());

    public static void main(String[] args) {
        DualOrphanService service = new DualOrphanService();
        int[] codes = {5001, 5002, 5003, 5002, 5001, 5009}; // 5003 and 5009 orphans
        log.info("Two orphans: " + Arrays.toString(service.findTwoOrphans(codes)));
    }
}
